<!-- eslint-disable @typescript-eslint/no-explicit-any -->
<script setup lang="ts">const { loggedIn, user } = useUserSession(); const email = ref(''); const password = ref(''); const error = ref(''); async function login() { try { await $fetch('/api/auth/login', { method: 'POST', body: { email: email.value, password: password.value } }); await navigateTo('/dashboard') } catch (e: any) { error.value = e?.data?.statusMessage || 'Unable to sign in.' } }</script>
<template><main class="mx-auto max-w-2xl p-8"><UCard><h1 class="mb-6 text-2xl font-semibold">Situm Explore</h1><p v-if="loggedIn">Welcome back, {{ user?.email }}.</p><UButton v-if="loggedIn" to="/dashboard">Open dashboard</UButton><form v-else class="space-y-4" @submit.prevent="login"><UInput v-model="email" type="email" placeholder="Email" required /><UInput v-model="password" type="password" placeholder="Password" required /><UAlert v-if="error" color="error" :description="error" /><UButton type="submit">Sign in</UButton></form></UCard></main></template>
